import type { Wall, Column, Window, Door, Stair, NorthArrow, TextElement, ClipFrame, Point } from './types';
import type { Dimension } from './dimensionTypes';
import type { RoomRegion } from './regionTypes';
import { distance, wallRectangle, getAngle } from './geometry';

const SCALE = 4;
const PX = 100 * SCALE;

export function renderToPrintCanvas(canvas: HTMLCanvasElement, data: {
  walls: Wall[];
    columns: Column[];
      windows: Window[];
        doors: Door[];
          dimensions: Dimension[];
            stairs: Stair[];
              northArrows: NorthArrow[];
                texts: TextElement[];
                  regions: RoomRegion[];
                    clipFrame: ClipFrame | null;
                    }) {
                      const frame = data.clipFrame;
                        if (!frame) return;

                          const W = Math.round(frame.width * PX);
                            const H = Math.round(frame.height * PX);
                              canvas.width = W;
                                canvas.height = H;
                                  const ctx = canvas.getContext('2d');
                                    if (!ctx) return;

                                      ctx.fillStyle = '#fff';
                                        ctx.fillRect(0, 0, W, H);

                                          const rot = frame.rotation || 0;
                                            const cos = Math.cos(-rot);
                                              const sin = Math.sin(-rot);
                                                const toPrint = (p: Point) => ({
                                                    x: W / 2 + ((p.x - frame.x) * cos - (p.y - frame.y) * sin) * PX,
                                                        y: H / 2 + ((p.x - frame.x) * sin + (p.y - frame.y) * cos) * PX,
                                                          });

                                                            ctx.save();
                                                              ctx.beginPath();
                                                                ctx.rect(0, 0, W, H);
                                                                  ctx.clip();

                                                                    // ==========================================================
                                                                      // 1. المناطق (المطبخ والحمام)
                                                                        // ==========================================================
                                                                          for (const region of data.regions) {
                                                                              if (region.polygon.length < 3) continue;
                                                                                  const pts = region.polygon.map(toPrint);
                                                                                      ctx.fillStyle = region.type === 'kitchen' ? 'rgba(255,165,0,0.4)' : 'rgba(0,191,255,0.4)';
                                                                                          ctx.strokeStyle = region.type === 'kitchen' ? '#f80' : '#06c';
                                                                                              ctx.lineWidth = 1.5 * SCALE;
                                                                                                  ctx.beginPath();
                                                                                                      ctx.moveTo(pts[0].x, pts[0].y);
                                                                                                          for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
                                                                                                              ctx.closePath();
                                                                                                                  ctx.fill();
                                                                                                                      ctx.stroke();
                                                                                                                        }

                                                                                                                          // ==========================================================
                                                                                                                            // 2. الجدران (مفرغة + نفس اللون والسمك + أركان متصلة)
                                                                                                                              // ==========================================================
                                                                                                                                for (const wall of data.walls) {
                                                                                                                                    const rect = wallRectangle(wall);
                                                                                                                                        const a1 = toPrint(rect.faces[0].start);
                                                                                                                                            const a2 = toPrint(rect.faces[0].end);
                                                                                                                                                const b1 = toPrint(rect.faces[1].start);
                                                                                                                                                    const b2 = toPrint(rect.faces[1].end);

                                                                                                                                                        ctx.strokeStyle = '#666';
                                                                                                                                                            ctx.lineWidth = Math.max(2, wall.thickness * PX / 2);
                                                                                                                                                                ctx.lineCap = 'butt';
                                                                                                                                                                    ctx.lineJoin = 'miter';
                                                                                                                                                                        
                                                                                                                                                                            ctx.beginPath();
                                                                                                                                                                                ctx.moveTo(a1.x, a1.y);
                                                                                                                                                                                    ctx.lineTo(a2.x, a2.y);
                                                                                                                                                                                        ctx.stroke();

                                                                                                                                                                                            ctx.beginPath();
                                                                                                                                                                                                ctx.moveTo(b1.x, b1.y);
                                                                                                                                                                                                    ctx.lineTo(b2.x, b2.y);
                                                                                                                                                                                                        ctx.stroke();
                                                                                                                                                                                                          }

                                                                                                                                                                                                            // ==========================================================
                                                                                                                                                                                                              // 3. الأعمدة
                                                                                                                                                                                                                // ==========================================================
                                                                                                                                                                                                                  for (const col of data.columns) {
                                                                                                                                                                                                                      const pos = toPrint(col.position);
                                                                                                                                                                                                                          const w = col.width * PX;
                                                                                                                                                                                                                              const l = col.length * PX;
                                                                                                                                                                                                                                  ctx.save();
                                                                                                                                                                                                                                      ctx.translate(pos.x, pos.y);
                                                                                                                                                                                                                                          ctx.rotate(col.rotation || 0);
                                                                                                                                                                                                                                              ctx.fillStyle = '#888';
                                                                                                                                                                                                                                                  ctx.fillRect(-w / 2, -l / 2, w, l);
                                                                                                                                                                                                                                                      ctx.strokeStyle = '#555';
                                                                                                                                                                                                                                                          ctx.lineWidth = SCALE;
                                                                                                                                                                                                                                                              ctx.strokeRect(-w / 2, -l / 2, w, l);
                                                                                                                                                                                                                                                                  ctx.restore();
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                      // ==========================================================
                                                                                                                                                                                                                                                                        // 4. الأبواب (قص الجدار + قوس الفتح)
                                                                                                                                                                                                                                                                          // ==========================================================
                                                                                                                                                                                                                                                                            for (const door of data.doors) {
                                                                                                                                                                                                                                                                                if (!door.center) continue;
                                                                                                                                                                                                                                                                                    const pos = toPrint(door.center);
                                                                                                                                                                                                                                                                                        const w = door.width * PX;
                                                                                                                                                                                                                                                                                            const thickness = 0.1 * PX;

                                                                                                                                                                                                                                                                                                const wall = data.walls.find(w => w.id === door.wallId);
                                                                                                                                                                                                                                                                                                    const angle = wall ? getAngle(wall.start, wall.end) : 0;
                                                                                                                                                                                                                                                                                                        const doorAngle = angle + ((door as any).rotation || 0);

                                                                                                                                                                                                                                                                                                            ctx.save();
                                                                                                                                                                                                                                                                                                                ctx.translate(pos.x, pos.y);
                                                                                                                                                                                                                                                                                                                    ctx.rotate(doorAngle);

                                                                                                                                                                                                                                                                                                                        // قص الجدار عند فتحة الباب (مستطيل أبيض)
                                                                                                                                                                                                                                                                                                                            ctx.fillStyle = '#ffffff';
                                                                                                                                                                                                                                                                                                                                ctx.fillRect(-w / 2, -thickness, w, thickness * 2);

                                                                                                                                                                                                                                                                                                                                    // جسم الباب (خط أفقي)
                                                                                                                                                                                                                                                                                                                                        ctx.strokeStyle = '#080';
                                                                                                                                                                                                                                                                                                                                            ctx.lineWidth = 2 * SCALE;
                                                                                                                                                                                                                                                                                                                                                ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                    ctx.moveTo(-w / 2, 0);
                                                                                                                                                                                                                                                                                                                                                        ctx.lineTo(w / 2, 0);
                                                                                                                                                                                                                                                                                                                                                            ctx.stroke();

                                                                                                                                                                                                                                                                                                                                                                // ورقة الباب (خط منحني لأسفل)
                                                                                                                                                                                                                                                                                                                                                                    ctx.lineWidth = 1.5 * SCALE;
                                                                                                                                                                                                                                                                                                                                                                        ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                            ctx.moveTo(-w / 2, 0);
                                                                                                                                                                                                                                                                                                                                                                                ctx.lineTo(-w / 2, -thickness * 2);
                                                                                                                                                                                                                                                                                                                                                                                    ctx.stroke();

                                                                                                                                                                                                                                                                                                                                                                                        // قوس الفتح (Arc)
                                                                                                                                                                                                                                                                                                                                                                                            ctx.lineWidth = 1 * SCALE;
                                                                                                                                                                                                                                                                                                                                                                                                ctx.strokeStyle = '#080';
                                                                                                                                                                                                                                                                                                                                                                                                    ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                        ctx.arc(-w / 2, 0, thickness * 2, -Math.PI / 2, 0);
                                                                                                                                                                                                                                                                                                                                                                                                            ctx.stroke();

                                                                                                                                                                                                                                                                                                                                                                                                                ctx.restore();
                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                    // ==========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                      // 5. النوافذ (إطار كامل + اتجاه حسب الجدار)
                                                                                                                                                                                                                                                                                                                                                                                                                        // ==========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                          for (const win of data.windows) {
                                                                                                                                                                                                                                                                                                                                                                                                                              if (!win.center) continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                  const pos = toPrint(win.center);
                                                                                                                                                                                                                                                                                                                                                                                                                                      const w = win.width * PX;
                                                                                                                                                                                                                                                                                                                                                                                                                                          const thickness = 0.1 * PX;

                                                                                                                                                                                                                                                                                                                                                                                                                                              const wall = data.walls.find(w => w.id === win.wallId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  const angle = wall ? getAngle(wall.start, wall.end) : 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.save();
                                                                                                                                                                                                                                                                                                                                                                                                                                                          ctx.translate(pos.x, pos.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.rotate(angle);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // إطار النافذة الخارجي (أزرق)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.strokeStyle = '#06f';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ctx.lineWidth = 2 * SCALE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.strokeRect(-w / 2, -thickness, w, thickness * 2);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // الخط الداخلي للنافذة
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ctx.moveTo(0, -thickness);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.lineTo(0, thickness);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ctx.stroke();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.restore();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // ==========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 6. السلالم (منطقة البسطة + الدرجات + الخط الفاصل)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // ==========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (const stair of data.stairs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (stair.polygon.length < 3) continue;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const center = toPrint(stair.center);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const width = stair.width * PX;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const totalLength = stair.totalLength * PX;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const landingLength = stair.landingLength * PX;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.save();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.translate(center.x, center.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ctx.rotate(stair.rotation || 0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // حدود السلم (مستطيل)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.strokeStyle = '#888';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.lineWidth = 1.5 * SCALE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ctx.strokeRect(-totalLength / 2, -width / 2, totalLength, width);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // منطقة البسطة (Landing)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.fillStyle = 'rgba(128,128,128,0.2)';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillRect(-totalLength / 2, -width / 2, landingLength, width);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // الخط الفاصل بين البسطة والدرجات
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.strokeStyle = '#555';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.lineWidth = 2 * SCALE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ctx.moveTo(-totalLength / 2 + landingLength, -width / 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.lineTo(-totalLength / 2 + landingLength, width / 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.stroke();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // الدرجات (خطوط متوازية)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const treadCount = Math.round(stair.totalLength / stair.treadDepth) || 10;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.strokeStyle = '#888';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.lineWidth = 1 * SCALE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (let i = 1; i < treadCount; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const t = i / treadCount;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const x = -totalLength / 2 + totalLength * t;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (x > -totalLength / 2 + landingLength) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.moveTo(x, -width / 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.lineTo(x, width / 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.stroke();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.restore();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ==========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 7. الأبعاد (خطوط مساعدة + خط متقطع + رقم)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ==========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      for (const dim of data.dimensions) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const a = toPrint(dim.start);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const b = toPrint(dim.end);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // خط البعد المتقطع
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.strokeStyle = '#777';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ctx.lineWidth = 0.8 * SCALE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.setLineDash([4 * SCALE, 4 * SCALE]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.moveTo(a.x, a.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ctx.lineTo(b.x, b.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.stroke();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ctx.setLineDash([]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // الخطوط المساعدة (امتداد البعد)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const dx = b.x - a.x;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const dy = b.y - a.y;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const dist = Math.hypot(dx, dy) || 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const nx = -dy / dist;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const ny = dx / dist;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.strokeStyle = '#aaa';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ctx.lineWidth = 0.5 * SCALE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ctx.moveTo(a.x, a.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.lineTo(a.x + nx * 30, a.y + ny * 30);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ctx.stroke();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ctx.moveTo(b.x, b.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.lineTo(b.x + nx * 30, b.y + ny * 30);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ctx.stroke();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // قيمة البعد
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const offsetPx = (dim.offset || 0.5) * PX;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const mid = { x: (a.x + b.x) / 2 + nx * offsetPx, y: (a.y + b.y) / 2 + ny * offsetPx };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ctx.fillStyle = '#333';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.font = `bold ${16 * SCALE}px sans-serif`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ctx.textAlign = 'center';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.textBaseline = 'middle';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ctx.fillText(distance(dim.start, dim.end).toFixed(2), mid.x, mid.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ==========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 8. سهم الشمال
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // ==========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (const arrow of data.northArrows) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const pos = toPrint(arrow.position);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const size = arrow.size * SCALE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.save();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.translate(pos.x, pos.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ctx.rotate(arrow.rotation || 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillStyle = '#000';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.moveTo(0, -size);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ctx.lineTo(-size * 0.45, size * 0.45);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.lineTo(0, size * 0.2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.lineTo(size * 0.45, size * 0.45);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.closePath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ctx.fill();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.restore();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ==========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 9. النصوص
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ==========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              for (const text of data.texts) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const pos = toPrint(text.position);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.fillStyle = text.color || '#000';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ctx.font = `bold ${Math.max(10, text.fontSize * SCALE)}px sans-serif`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ctx.textAlign = 'center';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ctx.textBaseline = 'middle';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ctx.fillText(text.text, pos.x, pos.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ctx.restore();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }